from common import *
R = 'f1-frontend'
T = []

# ---------------------------------------------------------------- 341 rendering strategy
T.append(topic(341, 'choosing-a-rendering-strategy', R, 21, 'Choosing a Rendering Strategy per Page',
 ['Match static, server, client and streamed rendering to how fresh and personal a page is',
  'Use revalidation, streaming and partial hydration to mix strategies on one site',
  'Explain the cost each strategy moves to the build, the server or the device'],
 3, 12, [204],
 [text(341, 1, 'Ask two questions per page',
   'How often does the content change, and does it differ per user? A blog post changes rarely and is the same for everyone, so build it once as static HTML. A logged-in dashboard is personal and changes every minute, so render it per request or on the client. Most sites need several answers, one per kind of page.',
   ['freshness-personalisation']),
  text(341, 2, 'Worked example: a shop with 50,000 products',
   'Product pages are public and change a few times a day, which suits static HTML. A full rebuild at 20 ms per page takes 50,000 pages at 20 ms each, 1,000 seconds or about 17 minutes, too slow for every price change. Regenerating each page in the background when it is older than a few minutes keeps pages cached and fresh without rebuilding the site. The cart is personal, so it renders on the client.',
   ['revalidation']),
  diagram(341, 3, 'Picking per page', 'Freshness and personalisation decide; the rest is tuning.', ['freshness-personalisation'],
   ['Same for everyone and changes rarely: build static HTML', 'Same for everyone but changes often: static with background revalidation', 'Personal but must show content fast: render on the server per request, streaming slow parts', 'Highly interactive after login: render on the client', 'Mostly static with a few interactive widgets: hydrate only those widgets']),
  text(341, 4, 'Streaming and partial hydration',
   'Streaming sends the page shell and fast sections first, then fills slow sections as their data arrives, so one slow query does not hold back the whole page. Partial hydration, sometimes called islands, ships script only for the interactive parts of a mostly static page, so the device runs less code before it can respond.',
   ['streaming', 'islands']),
  text(341, 5, 'Trap: one strategy for the whole site',
   'Rendering every page on the client makes public pages slow to show and harder for crawlers; rendering every page per request on the server pays server time for pages that never change. Choose per route, and measure the pages that matter most.',
   ['freshness-personalisation'])],
 [mc('t341-a1', 'freshness-personalisation', 'A documentation site has 2,000 pages, the same for every reader, updated weekly. Which strategy fits best?',
   [('a', 'Render each page per request on the server'), ('b', 'Render everything on the client after login'), ('c', 'Build static HTML and serve it from a CDN'), ('d', 'Stream each page section by section')], 'c',
   'Unchanging, shared content is cheapest and fastest as prebuilt files.'),
  mc('t341-a2', 'revalidation', 'Prices on 50,000 product pages change a few times a day. What keeps pages fast and reasonably fresh?',
   [('a', 'Static pages regenerated in the background when stale'), ('b', 'A full rebuild of every page whenever any price changes'), ('c', 'Client rendering with no HTML from the server'), ('d', 'Server rendering with caching turned off')], 'a',
   'Background revalidation serves cached HTML and refreshes it after a set age.'),
  mc('t341-a3', 'streaming', 'An account page has a fast header and a slow order-history query. How can the header show sooner?',
   [('a', 'Cache the slow query in the browser forever'), ('b', 'Stream the shell first and fill the order history when ready'), ('c', 'Wait for both queries, then send the complete page in one go'), ('d', 'Move the whole page to static HTML')], 'b',
   'Streaming decouples fast and slow sections of one response.'),
  mc('t341-a4', 'islands', 'A marketing page is static except for a newsletter form and an image carousel. What reduces the script the device runs?',
   [('a', 'Hydrating the whole page as one application'), ('b', 'Rendering the page on the client instead'), ('c', 'Inlining all scripts into the HTML'), ('d', 'Hydrating only the form and the carousel')], 'd',
   'Partial hydration ships code only for the parts that need it.'),
  order('t341-a5', 'freshness-personalisation', 'Order these pages from most static to most dynamic rendering.',
   ['An “About us” page', 'A product page with prices', 'A personalised home feed', 'A live trading dashboard'],
   ['s3', 's1', 's4', 's2'], 'Rarely changing shared pages build statically; personal, live pages render per request or on the client.'),
  est('t341-a6', 'revalidation', 'A full static build takes 20 ms per page. About how many minutes does rebuilding 50,000 pages take?', 'minutes', 17,
   ['Pages build one at a time', 'No caching between builds'], '50,000 pages at 20 ms each, in minutes', '1,000 s ÷ 60 ≈ 17 minutes',
   'Sanity check: too slow to rebuild on each price change, which is why per-page revalidation exists.', 0.1, [1000, 1.7])],
 flash(341, [('Two questions per page?', 'How often it changes, and whether it differs per user.'),
             ('Background revalidation?', 'Serve cached static HTML; regenerate it after it is older than a set age.'),
             ('Islands?', 'Hydrate only the interactive parts of a mostly static page.')]),
 src([('web.dev: Rendering on the Web', 'https://web.dev/articles/rendering-on-the-web'),
      ('MDN: Cache-Control', 'https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control')]),
 deep(['freshness-personalisation', 'revalidation', 'streaming', 'islands'], 'Where each strategy does its work',
  ['Static generation renders HTML at build time. Requests are served from files, often on a CDN, so time to first byte is low and servers do little. The cost is the build: content is only as fresh as the last build, and very large sites take long to rebuild.',
   'Revalidation narrows that gap. A page is served from cache until it is older than a set age; the next request still gets the cached copy while the page regenerates in the background. HTTP has a matching idea in the stale-while-revalidate cache directive. Some platforms also allow regenerating a page on demand when its data changes.',
   'Server rendering per request builds HTML with fresh, personal data. The server pays for every request, and time to first byte includes the slowest data fetch unless the response is streamed. Streaming sends the shell and ready sections first and appends the rest in the same response as data arrives.',
   'Client rendering sends a small HTML shell and script that fetches data and builds the page in the browser. After the first load, navigation can be quick, but the first view waits for script to download and run, and slower devices feel it most.',
   'Hydration attaches behaviour to server-rendered HTML, which means running the page’s components on the device. Partial or progressive hydration limits that work to the interactive parts, or delays it until they are visible or used, reducing script cost on content-heavy pages.'],
  ['Sites with different kinds of page: public catalogue, personal account, interactive tools.', 'Pages where both first view speed and interactivity matter.'],
  ['Avoid client-only rendering for public pages that must show fast and be crawled.', 'Avoid per-request server rendering for content that is the same for everyone and rarely changes.'],
  ['Strategy', 'Freshness', 'Main cost'],
  [['Static build', 'As of the last build', 'Build time for large sites'],
   ['Static with revalidation', 'Within the revalidation age', 'Occasional background renders'],
   ['Server per request', 'Fresh and personal', 'Server time on every request'],
   ['Client rendering', 'Fresh after load', 'Script download and run on the device']],
  'Rebuild everything or revalidate per page?',
  ['50,000 product pages', '20 ms to render one page', 'Prices change a few times a day'],
  ['Full rebuild: 50,000 pages at 20 ms each is 1,000 s, about 17 minutes.', 'A price change would wait up to 17 minutes plus deploy time.', 'Revalidating a page when it is 5 minutes old renders only pages people visit.', 'A page viewed every second is rendered about once per 5 minutes instead of 300 times.'],
  'Per-page revalidation keeps large catalogues fresh within minutes without full rebuilds or per-request rendering.',
  'How the guidance frames it', 'Official documentation',
  'The web.dev article on rendering on the web compares static rendering, server rendering, client rendering and hydration, and notes that server and static rendering can show content sooner while full client rendering and heavy hydration add script cost on the device. MDN documents the stale-while-revalidate directive of Cache-Control, which lets a cache serve a stale response while it fetches a fresh one in the background.',
  [('“Server rendering is faster, so render everything per request.”', '“Static is faster still for shared content; I’d choose per page by freshness and personalisation.”'),
   ('“Hydration is free once the HTML is there.”', '“Hydration runs component code on the device; I’d limit it to the interactive parts.”')],
  ['Choose rendering per page by freshness and personalisation.', 'Revalidation keeps static pages fresh without full rebuilds.', 'Streaming stops one slow section from delaying the whole page.', 'Hydrate only what must be interactive.']),
 {"kind": "tradeoff", "title": "Render the product page", "prompt": "A shop has 50,000 product pages viewed by anonymous shoppers. Prices change a few times a day and must be correct within about 10 minutes. How should product pages render?",
  "choices": [{"id": "a", "label": "Static pages regenerated when older than 5 minutes", "feedback": "Right: shared content served from cache, fresh within the bound, and only visited pages are rebuilt."},
              {"id": "b", "label": "Render each page on the server for every request", "feedback": "Fresh, but every view pays server time for content that is the same for everyone."},
              {"id": "c", "label": "Render on the client from a product API", "feedback": "Shoppers and crawlers wait for script before seeing the product; slower phones suffer most."}],
  "correctId": "a",
  "reveal": "The cart and account sections are personal, so they render on the client or per request, while the product content stays static with revalidation. One site, several strategies."},
 see([(205, 'HTTP caching headers behind revalidation'), (202, 'The critical rendering path each strategy feeds')])))

# ---------------------------------------------------------------- 342 optimistic UI
T.append(topic(342, 'optimistic-ui-and-rollback', R, 22, 'Optimistic UI and Rolling Back Conflicts',
 ['Show the result of an action before the server confirms it, and know when not to',
  'Roll back cleanly on errors and on 409 or 412 conflicts',
  'Use versions so concurrent edits are detected instead of overwritten'],
 3, 11, [213],
 [text(342, 1, 'Assume success, prepare to undo',
   'An optimistic update changes the screen as soon as the user acts, then sends the request. If the server agrees, nothing more happens. If it fails, the interface restores the previous state and says what went wrong. For likes, renames and reordering this makes the app feel instant.',
   ['optimistic-update']),
  text(342, 2, 'Worked example: two people rename one card',
   'Asha and Ben both open card 42 at version 7. Asha renames it; her request says “if version is 7” and succeeds, making version 8. Ben’s rename also says “if version is 7”, so the server answers 412 Precondition Failed. Ben’s screen had already shown his title, so it rolls back to Asha’s title and offers to apply his change again.',
   ['conflicts', 'rollback']),
  diagram(342, 3, 'Life of an optimistic edit', 'Keep what you need to undo until the server answers.', ['rollback'],
   ['Save a snapshot of the item and its version', 'Apply the change on screen at once', 'Send the request with the version it was based on', 'On success, store the server’s new version', 'On failure or conflict, restore the snapshot and explain']),
  text(342, 4, 'When not to be optimistic',
   'Payments, bookings and anything the user cannot easily undo should wait for the server. So should actions that often fail validation on the server. Showing a success that later disappears is worse than a short spinner when the stakes are high.',
   ['optimistic-update']),
  text(342, 5, 'Trap: rolling back to a stale snapshot',
   'If two optimistic edits to one item are in flight and the first fails, restoring the snapshot taken before it can wipe the second edit too. Track pending changes per item, or refetch the item from the server after a failure instead of guessing.',
   ['rollback'])],
 [mc('t342-a1', 'optimistic-update', 'Which action is the best fit for an optimistic update?',
   [('a', 'Paying for an order'), ('b', 'Starring a message'), ('c', 'Transferring money between accounts'), ('d', 'Booking the last seat on a flight')], 'b',
   'Low stakes, rarely fails, and easy to undo on screen.'),
  mc('t342-a2', 'conflicts', 'A save sends “If-Match” with the version it read, and another user saved first. What should the server reply?',
   [('a', '200 OK, saving it over the other user’s earlier change'), ('b', '404 Not Found'), ('c', '412 Precondition Failed, so the client can resolve'), ('d', '500 Internal Server Error')], 'c',
   'The precondition was a version that no longer matches; the client must reconcile.'),
  mc('t342-a3', 'rollback', 'An optimistic rename fails with a network error. What should the interface do?',
   [('a', 'Restore the previous name and let the user retry'), ('b', 'Keep the new name and hope the next save works'), ('c', 'Reload the whole page without a message'), ('d', 'Show the new name greyed out with no explanation')], 'a',
   'Roll back to the confirmed state and make the failure visible.'),
  mc('t342-a4', 'conflicts', 'Why send the version you read with each update?',
   [('a', 'It makes the request smaller'), ('b', 'It lets the server and CDN cache the response for longer'), ('c', 'It replaces the need for authentication'), ('d', 'It lets the server detect an edit based on old data')], 'd',
   'Without it, the last request silently overwrites the earlier one.'),
  order('t342-a5', 'rollback', 'Order an optimistic update that may conflict.',
   ['Snapshot the item and its version', 'Show the change on screen', 'Send it with the version', 'Roll back and explain on 409 or 412'],
   ['s3', 's1', 's4', 's2'], 'Snapshot first, so there is something to restore if the server disagrees.'),
  est('t342-a6', 'optimistic-update', 'A like request takes 300 ms. A user likes 20 posts while scrolling. About how many seconds of spinners does an optimistic design save them in total?', 's', 6,
   ['Requests are not overlapped', 'Each spinner lasts one request'], '20 likes at 300 ms each', '6,000 ms is 6 s of waiting removed',
   'Sanity check: small per action, but it is the feeling of lag on every tap that optimistic updates remove.', 0.1, [0.3, 60])],
 flash(342, [('Optimistic update?', 'Show the result at once, send the request, undo on failure.'),
             ('409 or 412 on save?', 'Someone changed it first; roll back, show their version, offer to reapply.'),
             ('Not optimistic for?', 'Payments, bookings and other costly or often-rejected actions.')]),
 src([('MDN: 412 Precondition Failed', 'https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Status/412'),
      ('RFC 9110: HTTP Semantics (conditional requests)', 'https://www.rfc-editor.org/rfc/rfc9110')]),
 deep(['optimistic-update', 'rollback', 'conflicts'], 'How an optimistic update stays correct',
  ['The client keeps two views of an item: the last state the server confirmed and the state with pending local changes applied. The screen shows the second. Each pending change records what it changed so it can be undone or reapplied.',
   'The request carries the version the change was based on. Over HTTP this is often an entity tag sent in If-Match, or a version number in the body. The server applies the change only if the stored version still matches, then returns the new version.',
   'If another write happened first, the server rejects the request: 412 Precondition Failed when an If-Match precondition fails, or 409 Conflict when the application detects the clash itself. The client then drops its pending change, takes the server’s current state and decides: reapply automatically if the changes touch different fields, or ask the user.',
   'Network errors and timeouts are less clear: the write may or may not have happened. Sending an idempotency key with the request lets the client retry safely, and refetching the item settles what the server holds before the screen is corrected.',
   'Several pending edits to one item should be applied in order on top of the confirmed state. When one fails, rebuild the shown state from the confirmed state plus the remaining pending edits, rather than restoring a snapshot that predates them. Whatever happens, the user should see a short message that names the change that was undone and why, so a rollback never looks like a glitch or lost work.'],
  ['Frequent, low-stakes actions such as likes, renames, reordering and toggles.', 'Collaborative apps where edits are usually accepted.'],
  ['Avoid for payments, bookings and irreversible actions.', 'Avoid when the server often rejects the action, so rollbacks become common.'],
  ['Approach', 'Feels like', 'Risk'],
  [['Wait for the server', 'A short delay on every action', 'Slow-feeling interface'],
   ['Optimistic with versions', 'Instant', 'Occasional visible rollback'],
   ['Optimistic without versions', 'Instant', 'Silent overwrites of others’ edits']],
  'Waiting the user does not see',
  ['300 ms per request', '20 likes in a session', 'Requests are not overlapped'],
  ['Pessimistic: 20 likes at 300 ms each is 6,000 ms of spinners.', 'Optimistic: the screen changes at once; requests finish in the background.', 'If 1 in 200 likes fails, about one rollback per 10 sessions of this size.', 'Each rollback must be visible and explained.'],
  'The saving is per-tap responsiveness; the cost is a rare, explained rollback.',
  'What the HTTP standard defines', 'Official documentation',
  'RFC 9110 defines conditional requests: a client can send If-Match with an entity tag so that the server performs the method only if the resource still has that tag, and responds 412 Precondition Failed otherwise. This lets clients avoid the lost-update problem when several clients edit one resource. MDN also documents 409 Conflict for requests that conflict with the current state of the target.',
  [('“Optimistic means we ignore errors.”', '“It means we show the change first and roll back visibly when the server disagrees.”'),
   ('“The last save wins, that’s fine.”', '“I’d send the version so the server returns 412 instead of silently overwriting someone else.”')],
  ['Show low-stakes changes at once and undo on failure.', 'Send the version you read; expect 409 or 412 on conflicts.', 'Rebuild from confirmed state plus pending edits after a failure.', 'Wait for the server on costly or irreversible actions.']),
 {"kind": "predict", "title": "Two renames, one card", "prompt": "Asha and Ben both load card 42 at version 7. Asha renames it to “Launch plan” and her save succeeds. Ben, still on version 7, renames it to “Q3 launch” and his screen updates at once. What should Ben see a moment later?",
  "choices": [{"id": "a", "label": "“Q3 launch”, because his save came last", "feedback": "Only if the server ignores versions, which would silently overwrite Asha’s change."},
              {"id": "b", "label": "“Launch plan”, with a note that the card changed and an offer to reapply", "feedback": "Right: the server rejects the stale version, and his screen rolls back to the confirmed state."},
              {"id": "c", "label": "An error page until he reloads", "feedback": "A conflict is expected in collaborative apps; it should be handled in place."}],
  "correctId": "b",
  "reveal": "Ben’s request carried version 7, but the card is at version 8, so the server answers 412. His client restores the server’s title and lets him decide whether his rename should replace it."},
 see([(224, 'Idempotency keys for retried client requests'), (212, 'Server-side validation that can reject a change')])))

# ---------------------------------------------------------------- 343 multi-tab
T.append(topic(343, 'multi-tab-coordination', R, 23, 'Keeping Many Tabs in Sync',
 ['Explain why several tabs of one app drift apart',
  'Send changes between tabs with broadcast messages and storage events',
  'Elect one leader tab for work that should run once'],
 3, 11, [206],
 [text(343, 1, 'Every tab is its own app',
   'Each tab runs its own copy of the page with its own memory. Log out in one and the others still show the account; read a message in one and the unread badge in the others stays. Storage such as IndexedDB is shared by tabs of the same origin, but the screens only change when each tab learns that something changed.',
   ['tab-isolation']),
  text(343, 2, 'Worked example: logout everywhere',
   'A user has five tabs open and logs out in one. That tab clears its session and posts a “logged-out” message on a broadcast channel named for the app. The other four tabs receive it, clear their in-memory data and show the sign-in screen. Without the message, they would keep showing private data until their next request failed.',
   ['broadcast']),
  diagram(343, 3, 'Coordinating tabs', 'Share data through storage, signal through messages, run shared work once.', ['broadcast', 'leader'],
   ['Write the change to shared storage', 'Post a small message to the other tabs', 'Other tabs reload the changed data from storage', 'One tab holds a lock and runs shared work, such as a live connection', 'When it closes, another tab acquires the lock and takes over']),
  text(343, 4, 'One connection, not five',
   'If every tab opens its own live connection and polls the same API, five tabs mean five times the load. Using the Web Locks API, the tabs ask for one named lock; the tab that holds it keeps the connection and posts updates to the others. When that tab closes, the lock is released and a waiting tab takes over.',
   ['leader']),
  text(343, 5, 'Trap: sending whole state in every message',
   'Messages between tabs should say what changed, not carry the full app state. Large messages are copied into every tab, and tabs can apply them in different orders. Store the data once, send an identifier and a version, and let each tab read the current value.',
   ['broadcast'])],
 [mc('t343-a1', 'tab-isolation', 'A user marks a chat as read in one tab. Why does another tab still show it unread?',
   [('a', 'Each tab keeps its own in-memory state until told to refresh'), ('b', 'The browser blocks storage for the second tab'), ('c', 'The server pushes the read status to only the most recent tab'), ('d', 'Browsers cache the badge for an hour')], 'a',
   'Tabs share storage but not memory; something must tell the other tab to update.'),
  mc('t343-a2', 'broadcast', 'Which is a direct way for tabs of one origin to message each other?',
   [('a', 'Writing to a cookie and polling it every second'), ('b', 'Sending each message through the server'), ('c', 'A broadcast channel all tabs subscribe to'), ('d', 'Reading another tab’s memory directly')], 'c',
   'A broadcast channel delivers messages to other same-origin contexts listening on the same name.'),
  mc('t343-a3', 'leader', 'Six tabs each open a live connection to the same feed. What reduces this to one connection?',
   [('a', 'Closing the connection when a tab is hidden'), ('b', 'Having the server reject extra connections from the same user’s browser'), ('c', 'Opening the connection only on page reload'), ('d', 'One tab holds a named lock, keeps the connection and relays updates')], 'd',
   'Leader election with a lock gives one connection and automatic hand-over.'),
  mc('t343-a4', 'broadcast', 'What should a cross-tab message about an edited note contain?',
   [('a', 'The full application state, serialised'), ('b', 'The note’s id and new version'), ('c', 'The user’s session token'), ('d', 'A full copy of every note')], 'b',
   'Signal the change; each tab reads current data from shared storage.'),
  order('t343-a5', 'leader', 'Order how a leader tab hands over when it closes.',
   ['The leader tab closes', 'Its lock is released', 'A waiting tab acquires the lock', 'The new leader opens the connection and relays updates'],
   ['s3', 's1', 's4', 's2'], 'Holding the lock defines the leader, so releasing it is the hand-over.'),
  est('t343-a6', 'leader', 'Users keep about 4 tabs of an app open; 200,000 users are online. How many live connections does the server see without a leader tab?', 'connections', 800000,
   ['Each tab opens one connection without coordination'], '200,000 × 4', '200,000 × 4 = 800,000 connections',
   'Sanity check: with a leader tab it would be about 200,000, a quarter of the load.', 0.05, [200000, 50000])],
 flash(343, [('Why do tabs drift?', 'Each tab has its own memory; only storage is shared.'),
             ('Message other tabs?', 'A broadcast channel, or storage events for local storage changes.'),
             ('Run work once?', 'Elect a leader tab with a named lock; another takes over when it closes.')]),
 src([('MDN: Broadcast Channel API', 'https://developer.mozilla.org/en-US/docs/Web/API/Broadcast_Channel_API'),
      ('MDN: Web Locks API', 'https://developer.mozilla.org/en-US/docs/Web/API/Web_Locks_API')]),
 deep(['tab-isolation', 'broadcast', 'leader'], 'How tabs of one origin share and coordinate',
  ['Tabs, windows and workers of one origin each run as separate programs with their own memory. They share storage, such as cookies, local storage and IndexedDB, and the HTTP cache, but not memory. A change in storage does not by itself redraw another tab.',
   'Browsers provide signals. A storage event fires in other same-origin tabs when local storage changes. The Broadcast Channel API lets any same-origin context post a message to a named channel and receive messages from others on it. Messages are structured copies, so they should be small.',
   'A common pattern writes the change to shared storage first, then posts a message with the item’s id and version. Receivers read the item from storage and apply it only if the version is newer than what they show, which tolerates messages arriving late or twice.',
   'Some work should run once per user, not once per tab: a live connection, a sync loop, a periodic poll. The Web Locks API grants a named lock to one context at a time. The holder acts as leader; others wait for the same lock. When the holder’s tab closes, its lock is released and the next waiter becomes leader.',
   'Shared and service workers are alternatives: a shared worker can hold one connection for all tabs, and a service worker can intercept requests and message clients. They add their own lifetimes and browser support differences, so many apps combine a lock-elected leader with broadcast messages.'],
  ['Apps users keep open in several tabs: mail, chat, dashboards, documents.', 'Logout, theme and settings changes that must apply everywhere.'],
  ['Avoid one live connection per tab when one per user would do.', 'Avoid sending large state blobs between tabs.'],
  ['Mechanism', 'Good for', 'Limitation'],
  [['Storage events', 'Reacting to local storage changes', 'Local storage only; not fired in the writing tab'],
   ['Broadcast channel', 'Small messages between tabs', 'No delivery to closed tabs; no ordering across sources'],
   ['Lock-elected leader', 'Running shared work once', 'Hand-over gap when the leader closes']],
  'Connections with and without a leader tab',
  ['200,000 users online', 'About 4 tabs each (illustrative)', 'One live connection per tab without coordination'],
  ['Without a leader: 200,000 × 4 = 800,000 connections.', 'With a leader: one per user, about 200,000.', 'The server holds a quarter of the connections and sends each update once per user.', 'Other tabs get updates over the broadcast channel at no server cost.'],
  'Leader election turns per-tab cost into per-user cost.',
  'What browsers provide', 'Official documentation',
  'MDN documents the Broadcast Channel API as allowing basic communication between browsing contexts, such as windows and tabs, and workers on the same origin. It documents the Web Locks API as letting scripts in one tab or worker asynchronously acquire a lock, hold it while work is performed, then release it, so that only one context holds a given lock at a time.',
  [('“IndexedDB is shared, so tabs stay in sync.”', '“Storage is shared but screens aren’t; I’d broadcast a change message so other tabs reload.”'),
   ('“Each tab opens its own socket.”', '“I’d elect one leader tab with a lock to hold the socket and relay updates.”')],
  ['Tabs share storage, not memory.', 'Write to storage, then broadcast an id and version.', 'Elect a leader tab with a lock for work that should run once.', 'Apply only newer versions so late or repeated messages are harmless.']),
 {"kind": "predict", "title": "Logout in one of five tabs", "prompt": "A user has five tabs of a mail app open and clicks “Log out” in one. The app clears the session cookie but sends no message to other tabs. What do the other four tabs show?",
  "choices": [{"id": "a", "label": "The sign-in screen straight away", "feedback": "Nothing tells them to change; their screens are separate programs."},
              {"id": "b", "label": "The inbox, until they next make a request that fails", "feedback": "Right: their in-memory data stays visible until a request is rejected or they are told."},
              {"id": "c", "label": "A blank page, as the browser wipes them", "feedback": "Clearing a cookie does not clear other tabs’ memory or screens."}],
  "correctId": "b",
  "reveal": "Post a “logged-out” message on a broadcast channel so every tab clears its data and shows sign-in at once. Private data should not stay on screen in tabs the user forgot about."},
 see([(214, 'Service workers, another way to share work across tabs'), (218, 'Live connections a leader tab can own')])))
